command:
$ErrorActionPreference = 'Stop'
$forgeRoot = (Get-Location).Path
. '.forge-codex/instructions/scripts/Common.ps1'

& '.forge-codex/instructions/scripts/Verify-Ledger.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-NoPython.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-NoAttribution.ps1' -WorkspaceRoot $forgeRoot
& '.forge-codex/instructions/scripts/Validate-McpParity.ps1' -WorkspaceRoot $forgeRoot -ActualToolSnapshot (Join-Path $forgeRoot 'tests/fixtures/Mcp/mcp-tools-semantic-golden.json')

$forgeMcp = Read-JsonFile -Path (Join-Path $forgeRoot '.forge-codex/instructions/plans/mcp-tool-parity.json')
if ($forgeMcp.expected_tool_count -ne 53 -or $forgeMcp.tools.Count -ne 53) { throw 'MCP parity inventory must contain exactly 53 tools.' }
if (@($forgeMcp.tools.name | Sort-Object -Unique).Count -ne 53) { throw 'MCP parity tool names are not unique.' }
foreach ($forgeTool in $forgeMcp.tools) {
  if ($forgeTool.windows_status -ne 'passed') { throw "MCP tool is not passed: $($forgeTool.name)" }
  if (@($forgeTool.windows_implementation).Count -eq 0 -or @($forgeTool.tests).Count -eq 0 -or @($forgeTool.evidence).Count -eq 0) { throw "MCP tool lacks implementation, tests, or evidence: $($forgeTool.name)" }
}

$forgeFeaturePath = Join-Path $forgeRoot '.forge-codex/instructions/plans/feature-parity-matrix.json'
$forgeTsvPath = Join-Path $forgeRoot '.forge-codex/instructions/plans/feature-parity-matrix.tsv'
$forgeFeatures = Get-Content -LiteralPath $forgeFeaturePath -Raw -Encoding UTF8 | ConvertFrom-Json
$forgeTsv = @(Get-Content -LiteralPath $forgeTsvPath -Encoding UTF8 | ConvertFrom-Csv -Delimiter "`t")
if ($forgeFeatures.features.Count -ne 84 -or $forgeTsv.Count -ne 84) { throw 'Feature parity matrices must each contain 84 rows.' }
$forgeFields = @('id','category','feature','behavior','macos_evidence','windows_acceptance','status','windows_files','tests','evidence','adr')
foreach ($forgeJsonRow in $forgeFeatures.features) {
  $forgeMatches = @($forgeTsv | Where-Object id -eq $forgeJsonRow.id)
  if ($forgeMatches.Count -ne 1) { throw "TSV row cardinality mismatch: $($forgeJsonRow.id)" }
  foreach ($forgeField in $forgeFields) {
    if ([string]$forgeJsonRow.$forgeField -cne [string]$forgeMatches[0].$forgeField) { throw "Feature JSON/TSV mismatch: $($forgeJsonRow.id) field $forgeField" }
  }
}
$forgePassedIds = @('MCP-001','MCP-002','MCP-003','MCP-004','MCP-008','TOOL-001','TOOL-002','TOOL-003','TOOL-004','TOOL-005','TOOL-006','TOOL-007','TOOL-008')
foreach ($forgeId in $forgePassedIds) {
  $forgeRow = $forgeFeatures.features | Where-Object id -eq $forgeId | Select-Object -First 1
  if (-not $forgeRow -or $forgeRow.status -ne 'passed' -or -not $forgeRow.windows_files -or -not $forgeRow.tests -or -not $forgeRow.evidence) { throw "Qualified feature row is incomplete: $forgeId" }
}
foreach ($forgeId in @('MCP-005','MCP-006','MCP-007')) {
  $forgeRow = $forgeFeatures.features | Where-Object id -eq $forgeId | Select-Object -First 1
  if (-not $forgeRow -or $forgeRow.status -ne 'not_started') { throw "Deferred feature row status is invalid: $forgeId" }
}

$forgeCheckpointRelative = '.forge-codex/state/evidence/P14/dynamic-multi-project-workspace-authority-checkpoint.json'
$forgeReportRelative = '.forge-codex/state/validator-reports/P14-G14.json'
$forgeCheckpointPath = Join-Path $forgeRoot $forgeCheckpointRelative
$forgeReportPath = Join-Path $forgeRoot $forgeReportRelative
$forgeCheckpointHash = Get-FileSha256 -Path $forgeCheckpointPath
$forgeReportHash = Get-FileSha256 -Path $forgeReportPath
if ($forgeCheckpointHash -ne '90dde575618a0a7dab8727cd4d55c12ce35c3c64f2a6a04475da2ad23207ec1a') { throw 'Dynamic authority checkpoint hash mismatch.' }
if ($forgeReportHash -ne '7fdb1195213b2db7d06ba6d2b85507777d550bad108990729b3a1cb7acd0a56e') { throw 'Validator report hash mismatch.' }
$forgeCheckpoint = Read-JsonFile -Path $forgeCheckpointPath
if ($forgeCheckpoint.status -ne 'passed' -or $forgeCheckpoint.effective_exit_code -ne 0 -or $forgeCheckpoint.timed_out) { throw 'Dynamic authority checkpoint status is invalid.' }
if ($forgeCheckpoint.measured_result.selected_ctest_passed -ne 13 -or $forgeCheckpoint.measured_result.selected_ctest_failed -ne 0 -or $forgeCheckpoint.measured_result.contract_matrix_tools -ne 53 -or $forgeCheckpoint.measured_result.contract_matrix_cases -ne 212 -or $forgeCheckpoint.measured_result.final_registry_projects -ne 2 -or $forgeCheckpoint.measured_result.final_registry_aliases -ne 2) { throw 'Dynamic authority measured result is invalid.' }
$forgeReport = Read-JsonFile -Path $forgeReportPath
if ($forgeReport.phase -ne 'P14' -or $forgeReport.gate -ne 'G14' -or $forgeReport.decision -ne 'pass' -or @($forgeReport.failures).Count -ne 0) { throw 'Validator report disposition is invalid.' }

$forgeIndex = Read-JsonFile -Path (Join-Path $forgeRoot '.forge-codex/state/evidence-index.json')
$forgeCheckpointIndex = $forgeIndex.items | Where-Object id -eq 'P14-dynamic-multi-project-workspace-authority-checkpoint' | Select-Object -First 1
$forgeReportIndex = $forgeIndex.items | Where-Object id -eq 'P14-G14-validator-report' | Select-Object -First 1
if (-not $forgeCheckpointIndex -or $forgeCheckpointIndex.path -ne $forgeCheckpointRelative -or $forgeCheckpointIndex.sha256 -ne $forgeCheckpointHash) { throw 'Evidence index checkpoint binding is invalid.' }
if (-not $forgeReportIndex -or $forgeReportIndex.path -ne $forgeReportRelative -or $forgeReportIndex.sha256 -ne $forgeReportHash) { throw 'Evidence index validator binding is invalid.' }

$forgeDiagnosticRecordRelative = '.forge-codex/state/commands/20260827T120307003Z-26151f73.json'
$forgeDiagnosticRecord = Read-JsonFile -Path (Join-Path $forgeRoot $forgeDiagnosticRecordRelative)
if ($forgeDiagnosticRecord.exit_code -ne 1 -or $forgeDiagnosticRecord.timed_out) { throw 'Retained integrity diagnostic disposition is invalid.' }
foreach ($forgeStreamName in @('stdout','stderr')) {
  $forgeDiagnosticStreamPath = Join-Path $forgeRoot ([string]$forgeDiagnosticRecord.$forgeStreamName)
  if ((Get-FileSha256 -Path $forgeDiagnosticStreamPath) -ne [string]$forgeDiagnosticRecord."${forgeStreamName}_sha256") { throw "Integrity diagnostic stream hash mismatch: $forgeStreamName" }
}
$forgeDiagnosticError = Get-Content -Raw -LiteralPath (Join-Path $forgeRoot ([string]$forgeDiagnosticRecord.stderr))
if (-not $forgeDiagnosticError.Contains('Feature JSON/TSV mismatch: UI-013 field windows_acceptance')) { throw 'Retained integrity diagnostic signature is invalid.' }

$forgeSecondDiagnosticRelative = '.forge-codex/state/commands/20260827T120432403Z-b5dbf78d.json'
$forgeSecondDiagnostic = Read-JsonFile -Path (Join-Path $forgeRoot $forgeSecondDiagnosticRelative)
if ($forgeSecondDiagnostic.exit_code -ne 1 -or $forgeSecondDiagnostic.timed_out) { throw 'Second retained integrity diagnostic disposition is invalid.' }
foreach ($forgeStreamName in @('stdout','stderr')) {
  $forgeSecondStreamPath = Join-Path $forgeRoot ([string]$forgeSecondDiagnostic.$forgeStreamName)
  if ((Get-FileSha256 -Path $forgeSecondStreamPath) -ne [string]$forgeSecondDiagnostic."${forgeStreamName}_sha256") { throw "Second integrity diagnostic stream hash mismatch: $forgeStreamName" }
}
$forgeSecondError = Get-Content -Raw -LiteralPath (Join-Path $forgeRoot ([string]$forgeSecondDiagnostic.stderr))
if (-not $forgeSecondError.Contains('Feature JSON/TSV mismatch: UI-013 field windows_acceptance')) { throw 'Second retained integrity diagnostic signature is invalid.' }

$forgeCommandPath = Join-Path $forgeRoot ([string]$forgeCheckpoint.authoritative_command_record)
if ((Get-FileSha256 -Path $forgeCommandPath) -ne [string]$forgeReport.verified_hashes.command_record_sha256) { throw 'Authoritative command record hash mismatch.' }
$forgeCommand = Read-JsonFile -Path $forgeCommandPath
if ($forgeCommand.exit_code -ne 0 -or $forgeCommand.timed_out) { throw 'Authoritative command did not pass.' }
foreach ($forgeStreamName in @('stdout','stderr')) {
  $forgeStreamPath = Join-Path $forgeRoot ([string]$forgeCommand.$forgeStreamName)
  if ((Get-FileSha256 -Path $forgeStreamPath) -ne [string]$forgeCommand."${forgeStreamName}_sha256") { throw "Authoritative stream hash mismatch: $forgeStreamName" }
}
foreach ($forgeArtifact in $forgeCheckpoint.artifacts) {
  $forgeArtifactPath = Join-Path $forgeRoot ([string]$forgeArtifact.path)
  $forgeArtifactItem = Get-Item -LiteralPath $forgeArtifactPath
  if ($forgeArtifactItem.Length -ne [int64]$forgeArtifact.bytes -or (Get-FileSha256 -Path $forgeArtifactPath) -ne [string]$forgeArtifact.sha256) { throw "Artifact mismatch: $($forgeArtifact.path)" }
}
foreach ($forgeSource in $forgeCheckpoint.source_evidence) {
  $forgeSourcePath = Join-Path $forgeRoot ([string]$forgeSource.path)
  if ((Get-FileSha256 -Path $forgeSourcePath) -ne [string]$forgeSource.sha256) { throw "Source mismatch: $($forgeSource.path)" }
}

$forgeRun = Read-JsonFile -Path (Join-Path $forgeRoot '.forge-codex/state/run-state.json')
$forgeP14 = $forgeRun.phases | Where-Object id -eq 'P14' | Select-Object -First 1
$forgeG14 = $forgeRun.gates | Where-Object id -eq 'G14' | Select-Object -First 1
if ($forgeRun.status -ne 'in_progress' -or $forgeRun.active_phase -ne 'P14' -or $forgeRun.active_role -ne 'validator' -or $forgeP14.status -ne 'passed' -or $forgeG14.status -ne 'passed') { throw 'Run-state P14/G14 disposition is invalid.' }
if ('.forge-codex/state/gate-results/G14.json' -notin $forgeP14.evidence) { throw 'P14 phase evidence is missing the G14 result.' }
foreach ($forgeEvidence in @($forgeReportRelative,[string]$forgeCheckpoint.authoritative_command_record,$forgeCheckpointRelative)) {
  if ($forgeEvidence -notin $forgeP14.evidence -or $forgeEvidence -notin $forgeG14.evidence) { throw "P14/G14 evidence binding is missing: $forgeEvidence" }
}
$forgeGate = Read-JsonFile -Path (Join-Path $forgeRoot '.forge-codex/state/gate-results/G14.json')
if ($forgeGate.status -ne 'passed' -or $forgeGate.role -ne 'validator' -or @($forgeGate.failures).Count -ne 0) { throw 'G14 gate result is invalid.' }

$forgeJsonPaths = @(
  @(git diff --name-only -- '*.json')
  @(git ls-files --others --exclude-standard -- '*.json')
) | Sort-Object -Unique
foreach ($forgeJsonRelative in $forgeJsonPaths) {
  $null = Get-Content -LiteralPath (Join-Path $forgeRoot $forgeJsonRelative) -Raw -Encoding UTF8 | ConvertFrom-Json
}
$forgeTextPaths = @(
  @(git diff --name-only)
  @(git ls-files --others --exclude-standard)
) | Sort-Object -Unique
$forgeUtf8 = [Text.UTF8Encoding]::new($false, $true)
foreach ($forgeTextRelative in $forgeTextPaths) {
  $forgeTextPath = Join-Path $forgeRoot $forgeTextRelative
  if (-not (Test-Path -LiteralPath $forgeTextPath -PathType Leaf)) { throw "Missing changed text file: $forgeTextRelative" }
  $forgeBytes = [IO.File]::ReadAllBytes($forgeTextPath)
  if ($forgeBytes.Length -eq 0) { continue }
  if ($forgeBytes.Length -ge 3 -and $forgeBytes[0] -eq 0xEF -and $forgeBytes[1] -eq 0xBB -and $forgeBytes[2] -eq 0xBF) { throw "UTF-8 BOM found: $forgeTextRelative" }
  $forgeText = $forgeUtf8.GetString($forgeBytes)
  if ([regex]::IsMatch($forgeText,'(?<!\r)\n') -or [regex]::IsMatch($forgeText,'\r(?!\n)') -or -not $forgeText.EndsWith("`r`n")) { throw "Non-CRLF formatting found: $forgeTextRelative" }
}
if (Select-String -LiteralPath (Join-Path $forgeRoot 'tests/Mcp/McpServeProcessSnapshotTests.cpp') -SimpleMatch -Pattern 'TRACE' -Quiet) { throw 'TRACE diagnostic remains in MCP process test.' }

git diff --check
if ($LASTEXITCODE -ne 0) { throw 'git diff --check failed.' }
Write-Output 'P14 final integrity passed: ledger 218 events, 53/53 MCP tools, 84 synchronized feature rows, 13 qualified feature rows, G14/P14 passed, 15 artifacts and 15 source hashes verified.'
